import 'package:flutter/material.dart';
import '../../../core/supabase/supabase_client.dart';

class ProfilePage extends StatefulWidget { const ProfilePage({super.key}); @override State<ProfilePage> createState()=>_ProfilePageState(); }
class _ProfilePageState extends State<ProfilePage>{Map<String,dynamic>? profile;List<Map<String,dynamic>> posts=[];bool loading=true;String? error;
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{try{final c=SupabaseClientProvider.client;final u=c.auth.currentUser;if(u==null)throw Exception('Not signed in');final r=await Future.wait([c.from('profiles').select('id,username,display_name,bio,avatar_url,location,created_at').eq('id',u.id).single(),c.from('posts').select('id,content,privacy,created_at,location_name').eq('profile_id',u.id).order('created_at',ascending:false).limit(50)]);if(mounted)setState((){profile=Map<String,dynamic>.from(r[0] as Map);posts=List<Map<String,dynamic>>.from(r[1] as List);});}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> _signOut()=>SupabaseClientProvider.client.auth.signOut();
 @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Text(error!));final p=profile!;final avatar='${p['avatar_url']??''}';return Scaffold(backgroundColor:const Color(0xfff7f8fc),body:RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.fromLTRB(16,18,16,110),children:[Container(height:190,decoration:BoxDecoration(borderRadius:BorderRadius.circular(28),gradient:const LinearGradient(colors:[Color(0xff171a3a),Color(0xff4630a5),Color(0xff14b8d4)]),boxShadow:const [BoxShadow(blurRadius:30,color:Color(0x302c1b69),offset:Offset(0,14))]),child:Stack(children:[Positioned(left:22,bottom:22,child:CircleAvatar(radius:50,backgroundColor:Colors.white,backgroundImage:avatar.isNotEmpty?NetworkImage(avatar):null,child:avatar.isEmpty?const Icon(Icons.person,size:48):null)),const Positioned(left:138,bottom:42,child:Text('WORK SOCIAL',style:TextStyle(color:Color(0xffa5f3fc),fontSize:12,fontWeight:FontWeight.w900,letterSpacing:2))),Positioned(right:12,top:12,child:IconButton(onPressed:_signOut,icon:const Icon(Icons.logout,color:Colors.white)))])),const SizedBox(height:16),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(24),boxShadow:const [BoxShadow(blurRadius:22,color:Color(0x160f172a),offset:Offset(0,8))]),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p['display_name']??'User',style:const TextStyle(fontSize:25,fontWeight:FontWeight.w900)),Text('@${p['username']??''}',style:const TextStyle(color:Color(0xff6366f1),fontWeight:FontWeight.w700)),if('${p['bio']??''}'.isNotEmpty)Padding(padding:const EdgeInsets.only(top:10),child:Text('${p['bio']}')),Wrap(spacing:8,children:[if('${p['location']??''}'.isNotEmpty)_badge(Icons.location_on_outlined,'${p['location']}'),_badge(Icons.article_outlined,'${posts.length} posts')])])),const SizedBox(height:18),const Text('Your posts',style:TextStyle(fontSize:18,fontWeight:FontWeight.w900)),...posts.map((post)=>Container(margin:const EdgeInsets.only(top:10),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20),boxShadow:const [BoxShadow(blurRadius:14,color:Color(0x120f172a))]),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.public,color:Color(0xff6366f1),size:18),const SizedBox(width:6),Text('${post['privacy']??''}'.toUpperCase(),style:const TextStyle(fontSize:11,fontWeight:FontWeight.w800,color:Color(0xff6366f1))),const Spacer(),Text('${post['created_at']??''}'.replaceFirst('T',' ').split('.').first,style:const TextStyle(fontSize:11,color:Colors.grey))]),if('${post['content']??''}'.isNotEmpty)Padding(padding:const EdgeInsets.only(top:10),child:Text('${post['content']}',style:const TextStyle(fontSize:15,height:1.35))),if('${post['location_name']??''}'.isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Text('${post['location_name']}',style:const TextStyle(color:Colors.grey)))])))])));}
 Widget _badge(IconData icon,String text)=>Chip(avatar:Icon(icon,size:16),label:Text(text),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(12))); }
